update public.lessons l set enhancements = $ench${"industryStory":"A team ran their whole suite on all three browsers on every push out of a belief that \"more coverage is safer\". Runs took twenty minutes, developers stopped waiting for them, and the cross-browser signal got ignored along with everything else. When they finally looked, almost none of the failures on Firefox and WebKit were real browser differences — they were the same flakes failing three times over. Cutting to full-Chromium-on-push plus a tagged critical subset on the other engines dropped the push run to four minutes and made the cross-browser failures, when they happened, worth reading.","visualAid":{"type":"comparison","title":"Where cross-browser budget is worth spending","headers":["Area","Varies by browser?","Cross-browser worth it?"],"rows":[["Business logic / API calls","No — same engine-independent code","No — one browser is enough"],["CSS layout & responsive design","Yes — engines lay out differently","Yes, especially WebKit"],["Form controls & date pickers","Yes — native widgets differ","Yes"],["Media playback & fonts","Yes — codec and rendering differences","Yes, where they matter to users"]]},"davidTip":"Set `grep` on a project, not `grepInvert` scattered through your tests, to build a cross-browser subset. Keeping the \"what runs where\" decision in the config means one place to read and change your matrix, instead of hunting for tags across hundreds of specs."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 11 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"order-dependent vs self-contained","bad":"~~~ts\n// Two tests coupled by shared state — safe only in serial, in this order.\nlet createdUserId: string;\n\ntest('creates a user', async ({ request }) => {\n  const res = await request.post('/api/users', { data: { name: 'Sam' } });\n  createdUserId = (await res.json()).id; // module-level, shared across workers\n});\n\ntest('deletes the user', async ({ request }) => {\n  await request.delete(`/api/users/${createdUserId}`); // undefined in another worker\n});\n~~~","good":"~~~ts\n// Each test creates and cleans up its own data — no coupling, no order.\ntest('creates and deletes a user', async ({ request }) => {\n  const res = await request.post('/api/users', {\n    data: { name: `Sam-${Date.now()}-${Math.random().toString(36).slice(2)}` },\n  });\n  const { id } = await res.json();\n\n  const check = await request.get(`/api/users/${id}`);\n  expect(check.ok()).toBeTruthy();\n\n  await request.delete(`/api/users/${id}`);\n});\n~~~"},"davidTip":"When you suspect a parallelism bug, `--repeat-each=10 --workers=4` is your best friend: it hammers the test concurrently and surfaces a collision that a single run hides. If it goes red under that and green at `--workers=1`, you have found a shared-state bug, not a flaky test — and the fix is isolation, never a retry.","miniChallenge":"Deliberately introduce a shared module-level variable across two tests, run them with four workers and `--repeat-each=5`, and watch them fail intermittently. Then remove the shared state and watch the failures disappear. Seeing it fail on purpose builds the instinct to spot it in review."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 11 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"visualAid":{"type":"flow","title":"A sharded run, end to end","steps":[{"label":"Split","detail":"CI matrix launches N jobs, each with --shard=i/N."},{"label":"Run in parallel","detail":"Each shard runs its disjoint slice, with workers inside it."},{"label":"Emit blobs","detail":"Each shard writes a blob report and uploads it as an artifact."},{"label":"Merge","detail":"A final job downloads all blobs and runs merge-reports."},{"label":"One result","detail":"A single HTML report, as if the suite ran on one machine."}]},"davidTip":"Keep the shard count in exactly one place if you can — a CI variable the matrix and the `--shard` flag both read — so bumping from four shards to eight is a one-line change, not a hunt for every hardcoded `/4`. Mismatched totals (a matrix of eight against `--shard=n/4`) silently run only half your tests, and a green report that quietly skipped half the suite is the worst kind of false confidence.","miniChallenge":"Time your suite on one machine, then as two shards, then as four. Plot the wall-clock times and note where the curve flattens — the point where adding shards stops paying off because the merge overhead and the slowest single test dominate. That knee in the curve is your practical shard limit."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 11 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"hard wait vs web-first assertion","bad":"~~~ts\n// Sleeps a fixed three seconds every run, ready or not — dead time times a thousand tests.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait page.waitForTimeout(3000);\nawait expect(page.getByText('Saved')).toBeVisible();\n~~~","good":"~~~ts\n// Waits only until the confirmation actually appears — usually a fraction of a second.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait expect(page.getByText('Saved')).toBeVisible();\n~~~"},"davidTip":"Ask Playwright where the time goes before you optimise: the HTML report lists per-test durations, and a quick sort surfaces the handful of tests eating the run. Speeding up the slowest ten is almost always cheaper and more effective than shaving a little off everything, and you will often find one `waitForTimeout` or one UI-login pattern behind most of the cost.","miniChallenge":"Grep your whole test directory for `waitForTimeout` and count the hits. Replace each with a web-first assertion on the thing the sleep was really waiting for, re-run the suite, and record how much wall-clock time those changes alone gave back."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 11 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team let their retry count creep up whenever a test got flaky — two retries, then three — until almost nothing ever failed the build on the first try. The suite was reliably green, and slowly, entirely useless: real regressions passed on retry alongside the flakes, and nobody could tell the difference. When a genuine bug finally shipped through a green pipeline, they rebuilt trust the hard way — dropped retries back to two, quarantined every test that needed a retry to pass, and gave each one an owner and a deadline. The quarantine list started long and shrank every week, and within a month a red build meant something again. The lesson they drew: retries measure flakiness, they do not fix it, and a suite that never fails is not necessarily a suite that works.","visualAid":{"type":"comparison","title":"Responses to a flaky test, ranked","headers":["Response","Keeps coverage?","Keeps the suite trusted?"],"rows":[["Fix the root cause","Yes","Yes — the ideal outcome"],["Quarantine with owner + ticket","Yes","Yes — blocking suite stays clean"],["Just add more retries","Yes","No — hides the signal, rot continues"],["Delete the test","No","Short term yes, but coverage is gone"],["Leave it failing at random","Yes","No — trains the team to ignore red"]]},"davidTip":"Put flake rate on the wall next to pass rate. Pass rate tells you today’s result; flake rate tells you whether people are about to stop believing it. When flake rate starts climbing, you have a narrow window to act before \"it’s probably just a flaky one\" becomes the team’s default reaction to every red — and once that habit forms, it is far harder to reverse than any individual flaky test is to fix.","miniChallenge":"Audit your last month of CI runs and build a ranked list of the tests that most often passed only on retry. Those are your top flakes. Pick the worst one, find why it is non-deterministic (timing, shared data, order), and fix it properly — then check whether your overall flake rate visibly drops. Fixing the worst offender usually moves the number more than you expect."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 11 and l.lesson_number = 5;

